// Fixed-Point LIF Neuron — Unverified Single-Neuron Verilog Prototype
// Q3.12 format (16-bit signed)
// Auto-generated by NB16 for PMUT Neuromorphic Project

module lif_neuron_fxp #(
    parameter INTEGER_BITS  = 3,
    parameter FRACTIONAL_BITS = 12,
    parameter TOTAL_BITS    = 16,
    parameter MAX_VAL       = 16'd32767,
    parameter MIN_VAL       = -16'd32768,
    parameter THRESHOLD     = 16'd4096,
    parameter BETA          = 16'd3686
) (
    input  wire                      clk,
    input  wire                      rst_n,
    input  wire [TOTAL_BITS-1:0]     i_current,
    input  wire                      i_valid,
    output reg                       o_spike,
    output reg  [TOTAL_BITS-1:0]     o_membrane,
    output reg                       o_ready
);

    reg [TOTAL_BITS-1:0]   membrane;
    reg [2*TOTAL_BITS-1:0] mult_temp;

    localparam IDLE = 2'b00, COMPUTE = 2'b01, DONE = 2'b10;
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            membrane  <= {TOTAL_BITS}{1'b0};
            o_spike   <= 1'b0;
            o_membrane <= {TOTAL_BITS}{1'b0};
            o_ready   <= 1'b0;
            state     <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    o_ready <= 1'b0;
                    if (i_valid) state <= COMPUTE;
                end

                COMPUTE: begin
                    // Leak: beta * membrane (fixed-point multiply)
                    mult_temp = $signed(BETA) * $signed(membrane);
                    membrane <= (mult_temp >>> FRACTIONAL_BITS) + $signed(i_current);

                    // Saturation
                    if ($signed(membrane) > $signed(MAX_VAL))
                        membrane <= MAX_VAL;
                    else if ($signed(membrane) < $signed(MIN_VAL))
                        membrane <= MIN_VAL;

                    // Spike
                    if ($signed(membrane) >= $signed(THRESHOLD)) begin
                        o_spike <= 1'b1;
                        membrane <= $signed(membrane) - $signed(THRESHOLD);
                    end else begin
                        o_spike <= 1'b0;
                    end

                    o_membrane <= membrane;
                    o_ready <= 1'b1;
                    state <= DONE;
                end

                DONE: begin
                    o_ready <= 1'b0;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule


